('bmlt-endoenzyme1-practice-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Which enzyme is most specific for hepatocellular injury?","translation":"","options":["ALT","ALP","Amylase","CK-MB"],"correctIndex":0,"explanation":"ALT is more liver-specific than AST. नेपाली: ALT कलेजोको कोषिकामा बढी केन्द्रित हुन्छ।","explanationNe":"ALT कलेजोको कोषिकामा बढी केन्द्रित हुन्छ।","topic":"Clinical Enzymology & Endocrinology"}'::jsonb,true),
('bmlt-endoenzyme1-practice-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Marked elevation of ALP with raised GGT most strongly suggests?","translation":"","options":["Bone disease","Hepatobiliary disease","Hemolysis","Pancreatitis"],"correctIndex":1,"explanation":"Raised ALP with GGT supports a hepatobiliary source. नेपाली: ALP र GGT दुवै बढ्दा कलेजो/पित्तनलीको समस्या सोचिन्छ।","explanationNe":"ALP र GGT दुवै बढ्दा कलेजो/पित्तनलीको समस्या सोचिन्छ।","topic":"Clinical Enzymology & Endocrinology"}'::jsonb,true),
('bmlt-endoenzyme1-practice-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"Which enzyme is commonly elevated in acute pancreatitis?","translation":"","options":["Lipase","CK","ACP","LDH"],"correctIndex":0,"explanation":"Serum lipase is relatively specific and remains elevated longer. नेपाली: Acute pancreatitis मा lipase उपयोगी हुन्छ।","explanationNe":"Acute pancreatitis मा lipase उपयोगी हुन्छ।","topic":"Clinical Enzymology & Endocrinology"}'::jsonb,true),
('bmlt-endoenzyme1-practice-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"The enzyme mainly used as a marker of myocardial injury in current practice is?","translation":"","options":["ALT","Troponin (not an enzyme)","ALP","Amylase"],"correctIndex":1,"explanation":"Cardiac troponin is the preferred biomarker; it is a protein, not an enzyme. नेपाली: Troponin enzyme होइन, तर मुटुको चोटको प्रमुख marker हो।","explanationNe":"Troponin enzyme होइन, तर मुटुको चोटको प्रमुख marker हो।","topic":"Clinical Enzymology & Endocrinology"}'::jsonb,true),
