('bmlt-endoenzyme1-practice-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Which enzyme is most associated with cholestasis?","translation":"","options":["ALP","CK","Amylase","Acid phosphatase"],"correctIndex":0,"explanation":"ALP rises in cholestasis; GGT helps confirm hepatic origin. नेपाली: पित्तको अवरोधमा ALP बढ्छ।","explanationNe":"पित्तको अवरोधमा ALP बढ्छ।","topic":"Clinical Enzymology & Endocrinology"}'::jsonb,true),
