('bmlt-endoenzyme1-practice-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"Which CK isoenzyme is predominantly found in skeletal muscle?","translation":"","options":["CK-MM","CK-MB","CK-BB","CK-AB"],"correctIndex":0,"explanation":"CK-MM is the major skeletal-muscle isoenzyme. नेपाली: CK-MM skeletal muscle मा बढी हुन्छ।","explanationNe":"CK-MM skeletal muscle मा बढी हुन्छ।","topic":"Clinical Enzymology & Endocrinology"}'::jsonb,true),
('bmlt-endoenzyme1-practice-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"Which enzyme is used to assess alcohol-related or cholestatic liver conditions alongside other tests?","translation":"","options":["GGT","Trypsin","Cholinesterase only","Amylase"],"correctIndex":0,"explanation":"GGT is sensitive but not specific; interpret with clinical context. नेपाली: GGT एक्लैले रोग पुष्टि गर्दैन।","explanationNe":"GGT एक्लैले रोग पुष्टि गर्दैन।","topic":"Clinical Enzymology & Endocrinology"}'::jsonb,true),
