-- BMLT NHPC: Clinical Enzymology & Endocrinology
-- 25 MCQ Practice + 25 Mock Test; unique IDs; safe to rerun.
begin;
on conflict (content_id) do nothing;
commit;

select content_type, count(*) as total
from public.learning_content
where faculty='BMLT'
  and subject='BMLT NHPC Licensing'
  and content_data->>'topic'='Clinical Enzymology & Endocrinology'
group by content_type
order by content_type;